/* ===== 営業カレンダー用レスポンシブ ===== */
/* ===== PCは通常表示 ===== */
/* =========================
   営業日テーブル
========================= */
/* =========================
   営業日テーブル
   最終版
   - 上固定は1行のみ
   - 左2列固定
   - PC 左2列=30%
   - SP 左2列=50%
   - 日付14列は均等
========================= */

.holiday-table-wrap {
  margin: 24px 0;
}

.holiday-table-note {
  margin: 0 0 10px;
  font-size: 14px;
  line-height: 1.6;
  color: #666;
}

.responsive-table {
  overflow: auto;
  -webkit-overflow-scrolling: touch;
  border: 1px solid #d9dce1;
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.04);
  max-height: 78vh;
}

/* ===== PC ===== */
:root {
  --days: 14;
  --col-store: 15%;
  --col-type: 15%;
  --col-left-total: 30%;
  --col-day: calc((100% - var(--col-left-total)) / var(--days));
  --head-row: 46px;
}

.table_vc {
  width: 100%;
  min-width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  table-layout: fixed;
  font-size: 14px;
  line-height: 1.45;
  background: #fff;
}

.table_vc th,
.table_vc td {
  padding: 8px 4px;
  border-right: 1px solid #d9dce1;
  border-bottom: 1px solid #d9dce1;
  vertical-align: middle;
  text-align: center;
  white-space: nowrap;
  background: #fff;
  box-sizing: border-box;
}

/* ===== 上1行だけ固定 ===== */
.table_vc thead th {
  position: sticky;
  top: 0;
  z-index: 30;
  background: #f7f8fa;
  font-weight: 700;
  height: var(--head-row);
  padding: 6px 3px;
}

/* 左上1列目 */
.table_vc thead th:first-child {
  position: sticky;
  left: 0;
  z-index: 42;
  width: var(--col-store);
  min-width: var(--col-store);
  max-width: var(--col-store);
  background: #eef2f6;
  box-shadow: 1px 0 0 #d9dce1;
}

/* 左上2列目 */
.table_vc thead th:nth-child(2) {
  position: sticky;
  left: var(--col-store);
  z-index: 41;
  width: var(--col-type);
  min-width: var(--col-type);
  max-width: var(--col-type);
  background: #eef2f6;
  box-shadow: 1px 0 0 #d9dce1;
}

/* 日付列 */
.table_vc thead th:nth-child(n + 3),
.table_vc tbody td:nth-child(n + 3) {
  width: var(--col-day);
  min-width: var(--col-day);
  max-width: var(--col-day);
}

.table_vc .vccol,
.table_vc thead th:nth-child(n + 3) {
  font-size: 11px;
  line-height: 1.15;
}

/* ===== 左1列目 ===== */
.table_vc tbody td.store {
  position: sticky;
  left: 0;
  z-index: 22;
  width: var(--col-store);
  min-width: var(--col-store);
  max-width: var(--col-store);
  text-align: left;
  white-space: normal;
  word-break: break-word;
  line-height: 1.4;
  font-weight: 700;
  background: #f7f8fa !important;
  box-shadow: 1px 0 0 #d9dce1;
}

/* 同一店舗の2行目以降 */
.table_vc tbody td.store.is-sub {
  color: transparent;
}

/* ===== 左2列目 ===== */
.table_vc tbody td:nth-child(2) {
  position: sticky;
  left: var(--col-store);
  z-index: 21;
  width: var(--col-type);
  min-width: var(--col-type);
  max-width: var(--col-type);
  white-space: normal;
  word-break: break-word;
  line-height: 1.3;
  font-weight: 700;
  background: #fff !important;
  box-shadow: 1px 0 0 #d9dce1;
}

/* 日付セル */
.table_vc tbody td:nth-child(n + 3) {
  font-size: 14px;
  font-weight: 700;
}

/* 固定列以外の交互背景 */
.table_vc tbody tr:nth-child(even) td:nth-child(n + 3) {
  background: #fcfcfd;
}

/* 土曜 */
.table_vc .sat {
  background: #f3f8ff !important;
  color: #0f4c81;
}

/* 日祝 */
.table_vc .sun {
  background: #fff5f5 !important;
  color: #b42318;
}

/* 休業 */
.table_vc .isclose {
  background: #fff1f1 !important;
  color: #c62828;
  font-weight: 700;
}

/* 罫線 */
.table_vc tr > *:first-child {
  border-left: 0;
}

.table_vc thead tr:first-child > * {
  border-top: 0;
}

/* ===== タブレット ===== */
@media (max-width: 1024px) {
  :root {
    --col-store: 15%;
    --col-type: 15%;
    --col-left-total: 30%;
    --col-day: calc((100% - var(--col-left-total)) / var(--days));
    --head-row: 42px;
  }

  .table_vc {
    min-width: 980px;
    font-size: 13px;
  }

  .table_vc th,
  .table_vc td {
    padding: 7px 3px;
  }

  .table_vc thead th:nth-child(n + 3) {
    font-size: 10px;
  }

  .table_vc tbody td:nth-child(n + 3) {
    font-size: 13px;
  }
}

/* ===== スマホ ===== */
@media (max-width: 767px) {
  :root {
    /* 左2列で約46% */
    --col-store: 24vw;
    --col-type: 22vw;
    --col-day: 44px;
    --head-row: 40px;
  }

  .holiday-table-note {
    font-size: 13px;
  }

  .responsive-table {
    border-radius: 10px;
    max-height: 72vh;
  }

  .table_vc {
    width: max-content;
    min-width: calc(var(--col-store) + var(--col-type) + (var(--col-day) * 14));
    font-size: 12px;
    border-collapse: separate;
    border-spacing: 0;
    table-layout: fixed;
  }

  .table_vc th,
  .table_vc td {
    padding: 7px 4px;
    box-sizing: border-box;
  }

  /* ヘッダー全体 */
  .table_vc thead th {
    position: sticky;
    top: 0;
    z-index: 25;
    background: #f7f8fa;
    font-size: 10px;
    line-height: 1.1;
    padding: 5px 2px;
  }

  /* ヘッダー 左1列 */
  .table_vc thead th:first-child {
    position: sticky;
    left: 0;
    z-index: 40;
    width: var(--col-store);
    min-width: var(--col-store);
    max-width: var(--col-store);
    background: #eef2f6 !important;
    box-shadow: none !important;
  }

  /* ヘッダー 左2列 */
  .table_vc thead th:nth-child(2) {
    position: sticky;
    left: var(--col-store);
    z-index: 39;
    width: var(--col-type);
    min-width: var(--col-type);
    max-width: var(--col-type);
    background: #eef2f6 !important;
    box-shadow: none !important;
  }

  /* 日付列 */
  .table_vc thead th:nth-child(n + 3),
  .table_vc tbody td:nth-child(n + 3) {
    width: var(--col-day);
    min-width: var(--col-day);
    max-width: var(--col-day);
  }

  /* 本文 左1列 */
  .table_vc tbody td.store {
    position: sticky;
    left: 0;
    z-index: 30;
    width: var(--col-store);
    min-width: var(--col-store);
    max-width: var(--col-store);
    font-size: 11px;
    line-height: 1.3;
    white-space: normal;
    word-break: break-word;
    overflow-wrap: anywhere;
    text-align: left;
    background: #f7f8fa !important;
    box-shadow: none !important;
  }

  /* 同一店舗の2行目以降 */
  .table_vc tbody td.store.is-sub {
    color: transparent;
  }

  /* 本文 左2列 */
  .table_vc tbody td:nth-child(2) {
    position: sticky;
    left: var(--col-store);
    z-index: 29;
    width: var(--col-type);
    min-width: var(--col-type);
    max-width: var(--col-type);
    font-size: 11px;
    line-height: 1.25;
    white-space: normal;
    word-break: break-word;
    overflow-wrap: anywhere;
    text-align: center;
    background: #fff !important;
    box-shadow: none !important;
  }

  /* 日付セル */
  .table_vc tbody td:nth-child(n + 3) {
    font-size: 12px;
  }
}


/* =========================================================
   ページ内リンク（アンカー）のスクロール停止位置の調整
   ヘッダーが被らないように、上部に余白を持たせてストップさせます。
   ========================================================= */

/* --- 1. 基本設定（PC用：1025px以上） --- */
/* PCのヘッダー高さ 120px 分を空けて止まる */
html {
    scroll-padding-top: 120px !important; 
    scroll-behavior: smooth; /* スムーススクロール（スゥーっと移動する動き）を有効化 */
}

/* --- 2. タブレット用（1024px以下） --- */
/* タブレットのヘッダー高さ 110px 分を空けて止まる */
@media (max-width: 1024px) {
    html {
        scroll-padding-top: 110px !important;
    }
}

/* --- 3. スマホ用（767px以下） --- */
/* スマホのヘッダー高さ 80px 分を空けて止まる */
@media (max-width: 767px) {
    html {
        scroll-padding-top: 80px !important;
    }
}


/* --- ポール・スミス エディション専用CTA --- */

/* 1. 通常時のスタイル：角丸を画像に合わせて調整 */
.btn-paulsmith .wp-block-button__link {
    background: linear-gradient(135deg, #F28C33 0%, #D9407D 100%) !important;
    color: #FFFFFF !important;
    font-weight: bold !important;
    /* 角丸を画像に合わせて「8px」に設定（丸すぎず、硬すぎない絶妙なライン） */
    border-radius: 8px !important; 
    padding: 18px 40px !important;
    box-shadow: 0 4px 12px rgba(217, 64, 125, 0.3) !important;
    transition: all 0.3s ease !important;
    border: none !important;
    text-decoration: none !important;
    display: inline-block !important;
    /* フォントサイズを固定し、ガタつきを防止 */
    font-size: 16px !important; 
    line-height: 1.5 !important;
}

/* 2. ホバー時の挙動：白文字の視認性を確保 */
.btn-paulsmith .wp-block-button__link:hover {
    /* 明るくしすぎず、彩度を少し上げることで「潰れ」を防止 */
    filter: saturate(1.2) contrast(1.1) !important; 
    /* 上に浮く動きを最小限にし、フォントサイズ変更は一切行わない */
    transform: translateY(-1px) !important;
    box-shadow: 0 6px 15px rgba(217, 64, 125, 0.5) !important;
    opacity: 1 !important;
    color: #FFFFFF !important;
    /* フォントサイズを通常時と同一に強制固定 */
    font-size: 16px !important; 
}



/* 1. Magazine記事用：PCでの2カラムを、スマホ表示時に反転させて縦並びにする設定 */
@media (max-width: 781px) {

    /* 2. カラム全体（親枠）の設定：スマホ時に左右のcolumnを入れ替え、下から上への縦並びに変更する */
    .wp-block-columns.reverse-sp {
        display: flex !important;
        flex-direction: column-reverse !important;
    }

    /* 3. 個別カラム（子枠）の設定：縦並びになった際、写真やテキストの枠が横に潰れないよう幅を100%にする */
    .wp-block-columns.reverse-sp > .wp-block-column {
        flex-basis: 100% !important;
        width: 100% !important;
        margin-left: 0 !important;
    }
}
.nicole-magazine-meta .elementor-icon-list-icon {
	margin-right: 6px !important;
}

