l":"<script>
document.addEventListener('DOMContentLoaded', function () {

  const getParamMap = (url) => {
    const map = new Map();
    url.searchParams.forEach((v, k) => {
      const set = map.get(k) || new Set();
      String(v).split(',').map(s => s.trim()).filter(Boolean).forEach(x => set.add(x));
      map.set(k, set);
    });
    return map;
  };

  const mapToSearchParams = (map) => {
    const sp = new URLSearchParams();
    map.forEach((set, key) => {
      const arr = Array.from(set);
      if (arr.length) sp.set(key, arr.join(','));
    });
    return sp;
  };

  const parseLinkFilter = (href) => {
    const u = new URL(href, window.location.origin);
    for (const [k, v] of u.searchParams.entries()) {
      return { key: k, value: v };
    }
    return null;
  };

  // active反映
  const applyActive = () => {
    const map = getParamMap(new URL(window.location.href));
    document.querySelectorAll('.filter-link').forEach(el => {
      const link = (el.tagName.toLowerCase() === 'a') ? el : el.querySelector('a');
      if (!link) return;

      const f = parseLinkFilter(link.href);
      if (!f) return;

      const set = map.get(f.key);
      const isOn = set && set.has(f.value);

      el.classList.toggle('is-active', !!isOn);
      link.classList.toggle('is-active', !!isOn);
    });
  };

  // クリックで条件を“積み上げ/解除”
  document.querySelectorAll('.filter-link').forEach(el => {
    const link = (el.tagName.toLowerCase() === 'a') ? el : el.querySelector('a');
    if (!link) return;

    link.addEventListener('click', function(e){
      const f = parseLinkFilter(link.href);
      if (!f) return;

      e.preventDefault();

      const nextUrl = new URL(window.location.href);
      const map = getParamMap(nextUrl);

      // 同一キーは複数選択（トグル）
      const set = map.get(f.key) || new Set();
      if (set.has(f.value)) set.delete(f.value);
      else set.add(f.value);

      if (set.size) map.set(f.key, set);
      else map.delete(f.key);

      nextUrl.search = mapToSearchParams(map).toString();
      window.location.href = nextUrl.toString();
    });
  });

  applyActive();
});
</script>
<script>
(function () {
  function openAllAccordions(scope) {
    // Elementor 新アコーディオン（details/summary型）
    scope.querySelectorAll('details').forEach(d => {
      d.open = true;
      d.setAttribute('open', 'open');
    });

    // Elementor のクラスがある場合も明示的に対応（新/旧混在対策）
    scope.querySelectorAll('.e-n-accordion-item').forEach(item => {
      item.setAttribute('open', 'open');
      item.open = true;
    });

    // 旧アコーディオン：見出しをクリックして開く（JSで確実に展開）
    scope.querySelectorAll('.elementor-accordion .elementor-tab-title, .elementor-toggle .elementor-tab-title').forEach(title => {
      // 既にアクティブならスキップ
      if (title.classList.contains('elementor-active')) return;
      title.click();
    });
  }

  function run() {
    const scope = document.querySelector('.bmw-filters');
    if (!scope) return;

    openAllAccordions(scope);

    // Elementorは後からDOMを差し替えることがあるので保険で再実行
    setTimeout(() => openAllAccordions(scope), 300);
    setTimeout(() => openAllAccordions(scope), 1000);
  }

  document.addEventListener('DOMContentLoaded', run);
})();
</script>

