[{"id":"248938c7","elType":"container","settings":{"flex_direction":"column","width":{"unit":"%","size":100,"sizes":[]},"boxed_width":{"unit":"%","size":100,"sizes":[]},"boxed_width_tablet":{"unit":"%","size":"","sizes":[]},"boxed_width_mobile":{"unit":"%","size":"","sizes":[]},"flex_gap":{"column":"10","row":"10","isLinked":true,"unit":"px","size":10},"background_background":"classic","__globals__":{"background_color":""},"animation":"fadeIn","flex_gap_mobile":{"column":"10","row":"10","isLinked":true,"unit":"px","size":10},"min_height_tablet":{"unit":"px","size":0,"sizes":[]},"flex_direction_tablet":"column","flex_direction_mobile":"row","flex_wrap_mobile":"nowrap","width_mobile":{"unit":"%","size":100,"sizes":[]},"custom_css":"/* --------------------------------------------------
 1. カード全体をクリック可能にする (a::after魔法)
 -------------------------------------------------- */
/* タイトル等の既存リンク(aタグ)から透明な膜を伸ばして全体を覆う */
selector a::after {
 content: '';
 position: absolute;
 top: 0;
 left: 0;
 width: 100%;
 height: 100%;
 z-index: 10;
 cursor: pointer;
}

/* 親コンテナの基準点設定 */
selector {
 position: relative;
 /* 画像が拡大した際のはみ出しをカットする */
 overflow: hidden; 
}

/* --------------------------------------------------
 2. 以前のアイキャッチ設定を復元 (表示の安定化)
 -------------------------------------------------- */
/* リンクタグをブロック要素にして幅を確保 */
selector a {
 display: block;
 width: 100%;
}

/* 画像をコンテナの幅に強制的に合わせる */
selector img {
 width: 100% !important;
 display: block;
 /* ズーム用のアニメーション速度設定 */
 transition: transform 0.5s ease !important;
}

/* --------------------------------------------------
 3. ホバー時の画像ズーム演出
 -------------------------------------------------- */
/* 親コンテナ(カード全体)にマウスが乗ったら、中の画像を拡大 */
selector:hover img {
 transform: scale(1.1) !important;
}"},"elements":[{"id":"7d7e35c1","elType":"container","settings":{"overflow":"hidden","boxed_width":{"unit":"%","size":100,"sizes":[]},"boxed_width_tablet":{"unit":"%","size":"","sizes":[]},"boxed_width_mobile":{"unit":"%","size":100,"sizes":[]},"flex_gap_tablet":{"column":"","row":"","isLinked":true,"unit":"px","size":null},"margin":{"unit":"px","top":"0","right":"0","bottom":"5","left":"0","isLinked":false},"_title":"画像","content_width":"full","width_mobile":{"unit":"%","size":30,"sizes":[]},"flex_justify_content_mobile":"flex-end","margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[{"id":"78663a8","elType":"widget","settings":{"__dynamic__":{"image":"[elementor-tag id="" name="post-featured-image" settings="%7B%22fallback%22%3A%7B%22url%22%3A%22%22%2C%22id%22%3A%22%22%2C%22size%22%3A%22%22%7D%7D"]","link":"[elementor-tag id="8ad68af" name="post-url" settings="%7B%7D"]"},"image_size":"full","width":{"unit":"%","size":100,"sizes":[]},"width_tablet":{"unit":"vw","size":"","sizes":[]},"object-fit":"cover","opacity":{"unit":"px","size":1,"sizes":[]},"opacity_hover":{"unit":"px","size":1,"sizes":[]},"_background_background":"classic","__globals__":{"_background_color":""},"height_mobile":{"unit":"px","size":65,"sizes":[]},"link_to":"custom","height_tablet":{"unit":"vh","size":20,"sizes":[]},"object-fit_tablet":"cover","object-position_tablet":"center center","height":{"unit":"vh","size":20,"sizes":[]},"width_mobile":{"unit":"%","size":100,"sizes":[]},"_title":"アイキャッチ画像"},"elements":[],"widgetType":"theme-post-featured-image"}],"isInner":true},{"id":"48fde83c","elType":"container","settings":{"flex_gap":{"column":"5","row":"5","isLinked":true,"unit":"px","size":5},"_title":"テキスト","boxed_width_mobile":{"unit":"%","size":100,"sizes":[]},"content_width":"full","width_mobile":{"unit":"%","size":70,"sizes":[]},"flex_justify_content_mobile":"flex-end"},"elements":[{"id":"7570a64d","elType":"widget","settings":{"__dynamic__"