}","_title":"TOCコンテナ"},"elements":[{"id":"c556db9","elType":"widget","settings":{"title":"Contents","exclude_headings_by_selector":[],"no_headings_message":"No headings were found on this page.","minimized_on":"mobile","collapse_subitems":"yes","border_width":{"unit":"px","size":0,"sizes":[]},"border_width_mobile":{"unit":"px","size":0,"sizes":[]},"border_radius":{"unit":"px","size":0,"sizes":[]},"border_radius_tablet":{"unit":"px","size":0,"sizes":[]},"border_radius_mobile":{"unit":"px","size":0,"sizes":[]},"header_separator_width":{"unit":"px","size":1,"sizes":[]},"header_separator_width_mobile":{"unit":"px","size":1,"sizes":[]},"padding":{"unit":"px","size":15,"sizes":[]},"padding_tablet":{"unit":"px","size":15,"sizes":[]},"padding_mobile":{"unit":"px","size":15,"sizes":[]},"heading_gap":{"unit":"px","size":0,"sizes":[]},"_element_width":"inherit","custom_css":"/* PC・スマホ共通：目次のインデントと余白を完全にゼロにする */

/* 1. リスト全体のコンテナと枠組みの余白を強制リセット */
selector .elementor-toc__list-wrapper,
selector .elementor-toc__list,
selector .elementor-toc__list-item {
    padding-left: 0 !important;
    margin-left: 0 !important;
    padding-right: 0 !important;
    margin-right: 0 !important;
    padding-inline-start: 0 !important; /* ブラウザ独自の余白リセット */
    list-style: none !important; /* リストマークによる余白発生を防止 */
}

/* 2. テキストエリアとリンクの余白・インデントをリセット */
selector .elementor-toc__list-item-text,
selector .elementor-toc__list-item-text a {
    padding-left: 0 !important;
    margin-left: 0 !important;
    text-indent: 0 !important; /* 1行目だけのインデントもリセット */
    display: inline-block !important;
    width: 100%;
}

/* 3. マーカー（アイコンや番号）周辺の隙間を排除 */
selector .elementor-toc__list-item i,
selector .elementor-toc__list-item::before {
    margin-right: 0 !important;
    padding-right: 0 !important;
}

/* 4. 階層（子リスト）がある場合も全て左に寄せる */
/* もし「2段目以降は少し右にずらしたい」場合は、この項目だけ削除してください */
selector .elementor-toc__list .elementor-toc__list {
    padding-left: 0 !important;
    margin-left: 0 !important;
}
