   魔法のコード：「全幅」ボタンを押したやつだけ
   1140pxの壁を無視して画面いっぱいに広げる
   =================================================== */
selector .alignfull {
    width: 100vw !important;    /* 画面の横幅いっぱい */
    max-width: 100vw !important;
    margin-left: calc(50% - 50vw) !important;  /* 左端まで引っ張る計算式 */
    margin-right: calc(50% - 50vw) !important; /* 右端まで引っ張る計算式 */

    /* 崩れ防止の保険 */
    padding: 0 !important;
    box-sizing: border-box !important;
}

/* 画像が変に引き伸ばされるのを防ぐ */
selector .alignfull img {
    width: 100%;
    height: auto;
    display: block;
}

