selector .elementor-button::after {
 content: "お気軽にお問合せください"; /* ★ここに吹き出しに出したい文字を入れる */
 position: absolute;
 right: 120%; /* ボタンの左側に配置 */
 top: 50%;
 transform: translateY(-50%) translateX(10px); /* 初期は少し右に隠す */
 background-color: #ffffff; /* 吹き出しの背景色 */
 color: #333333; /* 文字色 */
 padding: 10px 18px;
 border-radius: 4px;
 font-size: 14px;
 font-weight: normal;
 white-space: nowrap;
 opacity: 0;
 visibility: hidden;
 transition: all 0.3s ease-in-out; /* ヌルっと動くアニメーション */
 box-shadow: 0 4px 15px rgba(0,0,0,0.1);
 pointer-events: none;
}

/* --- 吹き出しの「しっぽ（三角形）」の作成 --- */
selector .elementor-button::before {
 content: "";
 position: absolute;
 right: calc(120% - 11px);
 top: 50%;
 transform: translateY(-50%) translateX(10px);
 border: 6px solid transparent;
 border-left-color: #ffffff; /* しっぽの色（背景色と合わせる） */
 opacity: 0;
 visibility: hidden;
 transition: all 0.3s ease-in-out;
 pointer-events: none;
}

/* --- ホバー時に表示する動き --- */
selector .elementor-button:hover::after,
selector .elementor-button:hover::before {
 opacity: 1;
 visibility: visible;
 transform: translateY(-50%) translateX(0); /* 横にスライドして定位置へ */
}

/* 吹き出しが見切れないようにする処理 */
selector .elementor-widget-container,
selector .elementor-button {
 overflow: visible !important;
}","__globals__":{"typography_typography":"","background_color":""}},"elements":[],"widgetType":"button"},{"id":"b97cd67","elType":"widget","settings":{"html":"<style>
/* 余計な干渉を完全に防ぎ、動きの制御をJSに一本化する */
#float-btn {
 transition: none !important;
 will-change: transform;
}
</style>

<script>
window.addEventListener('DOMContentLoaded', function() {
 var floatBtn = document.getElementById('float-btn');
 var footer = document.querySelector('footer, .elementor-location-footer');
 
 if (!floatBtn || !footer) return;

 var targetY = 0;
 var currentY = 0;
 var isAnimating = false;

 // サスペンションのように動きを滑らかにする魔法の関数
 function updatePosition() {
 // 現在地から目的地（targetY）に向かって、毎フレーム15%ずつ進む（Lerp処理）
 currentY += (targetY - currentY) * 0.15; 
 
 // GPUを使って描画
 floatBtn.style.transform = 'translate3d(0, -' + currentY + 'px, 0)';

 // 目的地にほぼ到着するまでアニメーションを継続
 if (Math.abs(targetY - currentY) > 0.5) {
 window.requestAnimationFrame(updatePosition);
 } else {
 // 完全に到着したらピタッと止める
 floatBtn.style.transform = 'translate3d(0, -' + targetY + 'px, 0)';
 currentY = targetY;
 isAnimating = false;
 }
 }

 // スクロール時の判定
 window.addEventListener('scroll', function() {
 var footerTop = footer.getBoundingClientRect().top;
 var windowHeight = window.innerHeight;

 // フッターが見えたら目的地（上に逃げる距離）を設定
 if (footerTop < windowHeight) {
 targetY = windowHeight - footerTop;
 } else {
 targetY = 0; // 見えなくなったら元の位置を目的地に
 }

 // アニメーションが止まっていたら再始動
 if (!isAnimating) {
 isAnimating = true;
 window.requestAnimationFrame(updatePosition);
 }
 }, { passive: true });
});
</script>","pa_condition_repeater":[]},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"8f091e6","elType":"container","settings":{"min_height":{"unit":"em","size":3,"sizes":[]},"min_height_tablet":{"unit":"em","size":"","sizes":[]},"min_height_mobile":{"unit":"px","size":0,"sizes":[]},"flex_justify_content":"center","background_background":"classic","background_color":"#000000","padding":{"unit":"px","top":"15","right":"60","bottom":"15","left":"60","isLinked":false},"padding_tablet":{"unit":"px","top":"15","right":"30","bottom":"15","left":"30","isLinked":false},"padding_mobile":{"unit":"px","top":"15","right":"20","bottom":"15","left":"20","isLinked":false},"_title":"パンくずリスト","width":{"unit":"px","size":1140,"sizes":[]},"background_color_stop_mobile":{"unit":"%","size":9},"background_color_b":"#000000","background_color_b_stop_mobile":{"unit":"%","size":0},"background_gradient_angle_mobile":{"unit":"deg","size":180},"border_border":"solid","border_width":{"unit":"px","top":"0","right":"0","bottom":"3","left":"0","isLinked":false},"border_width_mobile":{"unit":"px","top":"0","right":"0","bottom":"1","left":"0","isLinked":false},"border_color":"#FF0000","pa_condition_repeater":[]},"elements":[{"id":"7ca4f5b","elType":"widget","settings":{"typography_typography":"custom","typography_font_family":"Helvetica","typography_font_size":{"unit":"px","size":12,"sizes":[]},"typography_font_size_tablet":{"unit":"px","size":11,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":11,"sizes":[]},"typography_font_weight":"300","typography_line_height":{"unit":"em","size":1.3,"sizes":[]},"typography_line_height_tablet":{"unit":"em","size":1.2,"sizes":[]},"typography_line_height_mobile":{"unit":"em","size":1.2,"sizes":[]},"__globals__":{"typography_typography":"","link_color":"","link_hover_color":"globals/colors?id=909499e"},"text_color":"#FFFFFF","link_color":"#FFFFFF","_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"pa_c