"size":1.2,"sizes":[]},"icon_typography_line_height_mobile":{"unit":"em","size":1.2,"sizes":[]},"text_color":"#FFFFFF","__globals__":{"icon_typography_typography":""},"pa_condition_repeater":[]},"elements":[],"widgetType":"icon-list"}],"isInner":true},{"id":"a95dc6e","elType":"container","settings":{"content_width":"full","flex_justify_content_tablet":"flex-end","_title":"右","flex_gap_mobile":{"column":"0","row":"0","isLinked":false,"unit":"px","size":0},"width":{"unit":"%","size":50,"sizes":[]},"pa_condition_repeater":[]},"elements":[{"id":"11c81af","elType":"widget","settings":{"icon_list":[{"text":"Copyright © Nicole Group All Rights Reserved.","selected_icon":{"value":"","library":""},"_id":"a4be604"}],"space_between":{"unit":"px","size":0,"sizes":[]},"icon_align":"end","icon_align_mobile":"start","icon_size":{"unit":"px","size":6,"sizes":[]},"text_indent":{"unit":"px","size":0,"sizes":[]},"icon_typography_typography":"custom","icon_typography_font_family":"Helvetica","icon_typography_font_size":{"unit":"px","size":12,"sizes":[]},"icon_typography_font_size_tablet":{"unit":"px","size":11,"sizes":[]},"icon_typography_font_size_mobile":{"unit":"px","size":11,"sizes":[]},"icon_typography_font_weight":"300","icon_typography_line_height":{"unit":"em","size":1,"sizes":[]},"icon_typography_line_height_tablet":{"unit":"em","size":1.2,"sizes":[]},"icon_typography_line_height_mobile":{"unit":"em","size":1.2,"sizes":[]},"text_color":"#FFFFFF","__globals__":{"icon_typography_typography":""},"pa_condition_repeater":[]},"elements":[],"widgetType":"icon-list"}],"isInner":true}],"isInner":true}],"isInner":true}],"isInner":false},{"id":"10156d5","elType":"container","settings":{"flex_direction":"column","_title":"コンテナ","pa_condition_repeater":[]},"elements":[{"id":"41118ef2","elType":"widget","settings":{"html":"<script>
(function () {

 function detectBrand(pathname) {
 const p = (pathname || '').toLowerCase();
 if (p.startsWith('/bmw/')) return 'bmw';
 if (p.startsWith('/mini/')) return 'mini';
 if (p.startsWith('/rolls-royce/')) return 'rolls-royce';
 if (p.startsWith('/alpina/')) return 'alpina';
 if (p.startsWith('/ferrari/')) return 'ferrari';
 return 'nicole';
 }

 function normalizeTitle(title) {
 if (!title) return '';
 let t = String(title).trim();

 // 全角スペース→半角、連続スペース→1つ
 t = t.replace(/\u3000/g, ' ');
 t = t.replace(/\s+/g, ' ').trim();

 // 「 - TEST」削除
 t = t.replace(/\s*-\s*TEST\s*$/i, '');

 // SEOタイトルの後半を落とす（最初の " - " より後ろ）
 t = t.split(' - ')[0].trim();

 // 末尾のサイト名を落とす（残っている場合）
 t = t.replace(/\s*[｜|]\s*Nicole.*$/i, '').trim();

 // 先頭に「BMW 」が付くケースは外す（必要なら）
 t = t.replace(/^BMW\s+/, '');

 return t;
 }

 function getSourceTitle() {
 const h1 = document.querySelector('h1');
 if (h1 && h1.textContent) return normalizeTitle(h1.textContent);

 const og = document.querySelector('meta[property="og:title"]');
 if (og && og.content) return normalizeTitle(og.content);

 return normalizeTitle(document.title || '');
 }

 // ★クリックされた要素(.js-contact-link)から、実際のリンク(a)を特定してhrefを取る
 function getHrefFromElement(el) {
 if (!el) return '';

 // 自身がaならそれ
 if (el.tagName && el.tagName.toLowerCase() === 'a') {
 return el.getAttribute('href') || '';
 }

 // 自身にhref属性が付いてる場合（念のため）
 const ownHref = el.getAttribute && el.getAttribute('href');
 if (ownHref) return ownHref;

 // 子孫のaを探す（Elementorで外側にクラスが付くパターン対策）
 const innerA = el.querySelector ? el.querySelector('a[href]') : null;
 if (innerA) return innerA.getAttribute('href') || '';

 return '';
 }

 // ★ form_type を “絶対に落とさない”：
 // 1) data-form-type（外側でも内側aでもOK） 2) hrefのform_type 3) 現在URLのform_type 4) デフォルトinquiry
 function resolveFormType(el, clickedHref) {
 // data-form-type（外側）
 const dataTypeOuter = (el && el.getAttribute) ? (el.getAttribute('data-form-type') || '').trim() : '';
 if (dataTypeOuter) return dataTypeOuter;

 // data-form-type（内側a）
 const innerA = el && el.querySelector ? el.querySelector('a[data-form-type]') : null;
 if (innerA) {
 const dataTypeInner = (innerA.getAttribute('data-form-type') || '').trim();
 if (dataTypeInner) return dataTypeInner;
 }

 // hrefから読む
 try {
 const original = new URL(clickedHref || '', location.origin);
 const hrefType = original.searchParams.get('form_type');
 if (hrefType) return hrefType;
 } catch (e) {}

 // 現在URLから読む（contactページ直打ちのとき等）
 const pageType = new URLSearchParams(location.search).get('form_type');
 if (pageType) return pageType;

 return 'inquiry';
 }

 function buildContactUrl(clickedHref, el) {
 const brandSlug = detectBrand(location.pathname);
 const sourceTitle = getSourceTitle();

 const formType = resolveFormType(el, clickedHref);

 const to = new URL('/contact/', location.origin);
 to.searchParams.set('brand', brandSlug);

 // ★必ず付く
 if (formType) to.searchParams.set('form_type', formType);

 if (sourceTitle) to.searchParams.set('form_title', sourceTitle);

 // 保険：sessionStorageにも保存
 sessionStorage.setItem('ng_brand', brandSlug);
 if (sourceTitle) sessionStorage.setItem('ng_form_title', sourceTitle);

 return to.toString();
 }

 // ★イベント委譲：aでもdivでもbuttonでも拾う
 document.addEventListener('click', function (e) {
 const el = e.target && e.target.closest ? e.target.closest('.js-contact-link') : null;
 if (!el) return;

 // 新規タブ等は邪魔しない（実リンクがaの時だけ）
 const href = getHrefFromElement(el);
 let linkEl = null;
 if (el.tagName && el.tagName.toLowerCase() === 'a') linkEl = el;
 else if (el.querySelector) linkEl = el.querySelector('a[href]');

 if (linkEl && (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey)) return;

 const nextUrl = buildContactUrl(href, el);

 console.log('Clicked href:', href);
 console.log('Resolved form_type:', new URL(nextUrl).searchParams.get('form_type'));
 console.log('Generated contact URL:', nextUrl);

 e.preventDefault();
 location.href = nextUrl;
 }, true);

 // ついでに「見た目のhref」も差し替え（aタグだけ）
 document.querySelectorAll('a.js-contact-link').forEach((a) => {
 const href = a.getAttribute('href') || '';
 a.href = buildContactUrl(href, a);
 });

})();
</script>
","pa_condition_repeater":[]},"elements":[],"widgetType":"html"}],"isInner":false}]

[{"id":"12fa1cfb","elType":"container","settings":{"flex_direction":"column","content_width":"full","pa_condition_repeater":[],"flex_justify_content_mobile":"flex-start","css_classes":"location-card","custom_css":"/* =========================================================
 * Nicole Location Card
 * 店舗一覧 Loop Item 共通
 * ========================================================= */


/* ---------------------------------------------------------
 * カード全体
 * --------------------------------------------------------- */
selector.location-card {
	width: 100%;
}


/* ---------------------------------------------------------
 * 拠点情報
 * 高さはJavaScriptで同じ行ごとに自動調整
 * --------------------------------------------------------- */
selector .location-card__info {
	width: 100%;
}


/* ---------------------------------------------------------
 * ブランド
 * 文字サイズ等はElementor側で調整
 * --------------------------------------------------------- */
selector .location-card__brand {
	margin-bottom: 4px;
	font-weight: 600;
	line-height: 1.3;
}

selector .location-card__brand a {
	color: inherit;
	text-decoration: none;
	pointer-events: none;
}


/* ---------------------------------------------------------
 * 拠点種別
 * バッジ
 * --------------------------------------------------------- */
selector .location-card__type {
	display: inline-block;
	width: fit-content;
	max-width: 100%;

	margin-top: 4px;
	margin-bottom: 12px;
	padding: 4px 10px;

	border: 1px solid currentColor;
	border-radius: 999px;

	line-height: 1.3;
}

selector .location-card__type a {
	color: inherit;
	text-decoration: none;
}


/* ---------------------------------------------------------
 * 店舗詳細ボタン
 * --------------------------------------------------------- */
selector .location-card__button {
	margin-top: 12px;
	padding-top: 0;
}

selector .location-card__button .elementor-button-wrapper {
	width: 100%;
}

selector .location-card__button .elementor-button {
	border-style: solid;
	border-width: 1px;
}


/* ---------------------------------------------------------
 * スマホ
 * --------------------------------------------------------- */
@media (max-width: 767px) {

	selector .location-card__info {
		min-height: 0 !important;
	}

	selector .location-card__button {
		margin-top: 12px;
	}
