 * Nicole Location Loop Grid
 * ========================================================= */

selector .e-loop-item {
	min-width: 0;
}","post_query_include":[],"post_query_query_id":"nicole_location_dropdown_search","columns":3},"elements":[],"widgetType":"loop-grid"},{"id":"e9d14c9","elType":"widget","settings":{"html":"<script>
(function () {

	function equalizeNicoleLocationCards() {

		const cards = Array.from(
			document.querySelectorAll('.location-card')
		);

		if (!cards.length) {
			return;
		}

		const isMobile = window.matchMedia('(max-width: 767px)').matches;

		/* 一度すべて解除 */
		cards.forEach(function (card) {

			const info = card.querySelector('.location-card__info');

			if (info) {
				info.style.minHeight = '';
			}
		});

		/* スマホ1列では高さを揃えない */
		if (isMobile) {
			return;
		}

		/*
		 * カードの画面上のY座標を使って、
		 * 同じ横一列のカードをグループ化
		 */
		const rows = [];

		cards.forEach(function (card) {

			const rect = card.getBoundingClientRect();
			const top  = Math.round(rect.top);

			let row = rows.find(function (item) {
				return Math.abs(item.top - top) <= 5;
			});

			if (!row) {

				row = {
					top: top,
					cards: []
				};

				rows.push(row);
			}

			row.cards.push(card);
		});

		/*
		 * 各行ごとに
		 * 「拠点情報」の最大高さを取得して統一
		 */
		rows.forEach(function (row) {

			let maxHeight = 0;

			row.cards.forEach(function (card) {

				const info = card.querySelector('.location-card__info');

				if (!info) {
					return;
				}

				maxHeight = Math.max(
					maxHeight,
					info.scrollHeight
				);
			});

			if (!maxHeight) {
				return;
			}

			row.cards.forEach(function (card) {

				const info = card.querySelector('.location-card__info');

				if (info) {
					info.style.minHeight = maxHeight + 'px';
				}
			});
		});
	}


	let resizeTimer = null;

	function scheduleEqualize() {

		clearTimeout(resizeTimer);

		resizeTimer = setTimeout(
			equalizeNicoleLocationCards,
			100
		);
	}


	document.addEventListener(
		'DOMContentLoaded',
		function () {

			equalizeNicoleLocationCards();

			setTimeout(
				equalizeNicoleLocationCards,
				300
			);

			setTimeout(
				equalizeNicoleLocationCards,
				800
			);
		}
	);


	window.addEventListener(
		'load',
		equalizeNicoleLocationCards
	);


	window.addEventListener(
		'resize',
		scheduleEqualize
	);

})();
