				maxHeight = Math.max(
					maxHeight,
					info.scrollHeight
				);
			});

			if (!maxHeight) {
				return;
			}

			row.cards.forEach(function (card) {

				const info = card.querySelector('.location-card__info');

				if (info) {
					info.style.minHeight = maxHeight + 'px';
				}
			});
		});
	}


	let resizeTimer = null;

	function scheduleEqualize() {

		clearTimeout(resizeTimer);

		resizeTimer = setTimeout(
			equalizeNicoleLocationCards,
			100
		);
	}


	document.addEventListener(
		'DOMContentLoaded',
		function () {

			equalizeNicoleLocationCards();

			setTimeout(
				equalizeNicoleLocationCards,
				300
			);

			setTimeout(
				equalizeNicoleLocationCards,
				800
			);
		}
	);


	window.addEventListener(
		'load',
		equalizeNicoleLocationCards
	);


	window.addEventListener(
		'resize',
		scheduleEqualize
	);

})();
</script>","pa_condition_repeater":[],"_background_image":{"url":"","id":"","size":""},"_background_video_fallback":{"url":"","id":"","size":""},"_background_slideshow_gallery":[],"_background_hover_image":{"url":"","id":"","size":""},"_background_hover_video_fallback":{"url":"","id":"","size":""},"_background_hover_slideshow_gallery":[],"_mask_image":{"url":"","id":"","size":""}},"elements":[],"widgetType":"html"}],"isInner":true}],"isInner":false}]

[{"id":"670ba3f0","elType":"container","settings":{"flex_direction":"column","content_width":"full","pa_condition_repeater":[],"flex_justify_content_mobile":"flex-start","css_classes":"location-card","custom_css":"/* =========================================================
 * Nicole Location Card
 * 店舗一覧 Loop Item v4
 * ========================================================= */

selector.location-card {
	width: 100%;
}

selector .location-card__info {
	width: 100%;
}

selector .location-card__brand {
	margin-bottom: 4px;
	font-weight: 600;
	line-height: 1.3;
}

selector .location-card__brand a {
	color: inherit;
	text-decoration: none;
	pointer-events: none;
}

/* マップ連動番号：画像左上 */
selector .location-card__media {
	position: relative;
	overflow: hidden;
}

selector .location-card__map-number {
	position: absolute;
	top: 16px;
	left: 16px;
	z-index: 3;
	width: auto;
}

selector .location-card__map-number .elementor-widget-container {
	display: flex;
}

selector .location-card__map-number .nicole-location-map-number {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 44px;
	height: 44px;
	border-radius: 50%;
	background: #ea4335;
	color: #ffffff;
	font-size: 16px;
	font-weight: 700;
	line-height: 1;
	box-shadow: 0 2px 8px rgba(0, 0, 0, 0.22);
}

selector .location-card__map-number .nicole-location-map-number:focus-visible {
	outline: 3px solid #ffffff;
	outline-offset: 2px;
}

/* 対応サービス：名称の長さに関係なく50%幅 */
selector .location-card__services {
	display: block;
	width: 100%;
	max-width: none;
}

selector .nicole-location-capability-labels {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: 8px 10px;
	width: 100%;
	margin: 4px 0 12px;
}

selector .nicole-location-capability-labels__item {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 100%;
	max-width: none;
	min-width: 0;
	min-height: 34px;
	padding: 6px;
	border: 1px solid #111111;
	border-radius: 999px;
	background: #ffffff;
	color: #111111;
	font-size: 11px;
	font-weight: 600;
	line-height: 1.25;
	text-align: center;
	white-space: nowrap;
}

selector .nicole-location-capability-labels__item--rolls-royce {
	font-size: 10px;
	letter-spacing: -0.03em;
}

/* ボタン：一覧専用・黒で統一 */
selector .location-card__actions {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: 16px;
}

selector .location-card__actions > .elementor-element {
	width: 100%;
	min-width: 0;
}

selector .nicole-location-list-button {
	margin-top: 12px;
	padding-top: 0;
}

selector .nicole-location-list-button .elementor-button-wrapper {
	width: 100%;
	height: 100%;
}

selector .nicole-location-list-button .elementor-button {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 100%;
	height: 100%;
	border: 1px solid #111111 !important;
	background: #111111 !important;
	color: #ffffff !important;
}

selector .nicole-location-list-button .elementor-button:hover,
selector .nicole-location-list-button .elementor-button:focus-visible {
	border-color: #111111 !important;
	background: #ffffff !important;
	color: #111111 !important;
}

selector .nicole-location-list-button .elementor-button:hover svg,
selector .nicole-location-list-button .elementor-button:focus-visible svg {
	fill: #111111 !important;
}

@media (max-width: 767px) {
	selector .location-card__info {
		min-height: 0 !important;
	}

	selector .location-card__map-number {
		top: 12px;
		left: 12px;
	}

	selector .location-card__map-number .nicole-location-map-number {
		width: 40px;
		height: 40px;
		font-size: 15px;
	}

	selector .nicole-location-capability-labels {
		gap: 7px;
	}

	selector .nicole-location-capability-labels__item {
		padding-right: 6px;
		padding-left: 6px;
		font-size: 11px;
	}

	selector .nicole-location-capability-labels__item--rolls-royce {
		font-size: 9px;
	}

	/* ルートボタン：スマホではアイコンを外して一行表示 */
	selector .nicole-location-list-button--route .elementor-button-icon {
		display: none !important;
	}

	selector .nicole-location-list-button--route .elementor-button {
		padding-right: 8px !important;
		padding-left: 8px !important;
	}

	selector .nicole-location-list-button--route .elementor-button-text {
		white-space: nowrap;
	}
}
