  width: 100%;
  margin: 0 0 4px;
}

selector .nicole-location-capability-labels {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px 10px;
  width: 100%;
  margin: 0;
}

selector .nicole-location-capability-labels__item {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-width: 0;
  min-height: 34px;
  padding: 6px;
  border: 1px solid #111111;
  border-radius: 999px;
  background: #ffffff;
  color: #111111;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.25;
  text-align: center;
  white-space: nowrap;
}

selector .nicole-location-capability-labels__item--rolls-royce {
  font-size: 10px;
  letter-spacing: -0.03em;
}

@media (max-width: 767px) {
  selector .nicole-location-capability-labels {
    gap: 7px;
  }

  selector .nicole-location-capability-labels__item {
    padding-right: 6px;
    padding-left: 6px;
    font-size: 11px;
  }

  selector .nicole-location-capability-labels__item--rolls-royce {
    font-size: 9px;
  }
