left":"10","isLinked":true},"pa_condition_repeater":[]},"elements":[{"id":"fa03c1c","elType":"widget","settings":{"html":"<style>
  /*
   * =========================================================
   * Nicole Group formrun埋め込み
   * 本番 /contact/ 用
   *
   * ・確認画面はiframe内で表示
   * ・送信完了後はブラウザ全体で外部完了ページへ遷移
   * =========================================================
   */

  #formrun-wrapper {
    position: relative;
    width: 100%;
    scroll-margin-top: 120px;
  }

  #formrun-embed {
    width: 100%;
    min-height: 700px;
  }

  #formrun-embed iframe {
    display: block;
    width: 100% !important;
    max-width: 100% !important;
    border: 0 !important;
  }

  @media screen and (max-width: 767px) {
    #formrun-wrapper {
      scroll-margin-top: 24px;
    }

    #formrun-embed {
      min-height: 600px;
    }
  }
</style>

<div id="formrun-wrapper">
  <div
    id="formrun-embed"
    class="formrun-embed"
    data-formrun-redirect="true"
    aria-label="お問い合わせフォーム"
  ></div>
</div>

<script>
(function () {
  'use strict';

  const params = new URLSearchParams(window.location.search);

  /*
   * =========================================================
   * 基本設定
   * =========================================================
   */

  const DEFAULT_BRAND = 'nicole';

  /*
   * 固定ヘッダーとの重なりを避けるための余白
   */
  const SCROLL_OFFSET_PC = 120;
  const SCROLL_OFFSET_SP = 24;

  /*
   * 初回描画による高さ変更ではスクロールさせないため、
   * ページ表示後に監視を有効化するまでの時間
   */
  const OBSERVER_ARM_DELAY = 2500;

  /*
   * 小さな高さ変化では反応せず、
   * 入力画面と確認画面の切り替えだけを対象にする
   */
  const HEIGHT_CHANGE_THRESHOLD = 200;

  /*
   * formrun側の高さ確定を待つ時間
   */
  const SCROLL_DELAY = 180;

  /*
   * =========================================================
   * ブランド判定
   * URLパラメータ
   * → sessionStorage
   * → referrer
   * → Nicole Group
   * =========================================================
   */

  function detectBrandFromPath(pathname) {
    const path = String(pathname || '').toLowerCase();

    if (path.startsWith('/bmw/')) {
      return 'bmw';
    }

    if (path.startsWith('/mini/')) {
      return 'mini';
    }

    if (path.startsWith('/rolls-royce/')) {
      return 'rolls-royce';
    }

    if (path.startsWith('/alpina/')) {
      return 'alpina';
    }

    if (path.startsWith('/ferrari/')) {
      return 'ferrari';
    }

    return DEFAULT_BRAND;
  }

  /*
   * =========================================================
   * 車種・シリーズ名の整形
   * =========================================================
   */

  function normalizeTitle(title) {
    if (!title) {
      return '';
    }

    let normalizedTitle = String(title).trim();

    normalizedTitle = normalizedTitle.replace(/\u3000/g, ' ');
    normalizedTitle = normalizedTitle.replace(/\s+/g, ' ').trim();
    normalizedTitle = normalizedTitle.replace(
      /\s*-\s*TEST\s*$/i,
      ''
    );
    normalizedTitle = normalizedTitle
      .split(' - ')[0]
      .trim();
    normalizedTitle = normalizedTitle
      .replace(/\s*[｜|]\s*Nicole.*$/i, '')
      .trim();
    normalizedTitle = normalizedTitle.replace(
      /^BMW\s+/i,
      ''
    );

    return normalizedTitle;
  }

  /*
   * =========================================================
   * ブランド取得
   * =========================================================
   */

  let brandSlug = String(
    params.get('brand') || ''
  ).toLowerCase();

  if (!brandSlug) {
    brandSlug = String(
      sessionStorage.getItem('ng_brand') || ''
    ).toLowerCase();
  }

  if (!brandSlug) {
    try {
      const referrerPath = document.referrer
        ? new URL(document.referrer).pathname
        : '';

      brandSlug = detectBrandFromPath(referrerPath);
    } catch (error) {
      brandSlug = DEFAULT_BRAND;
    }
  }

  if (!brandSlug || brandSlug === 'group') {
    brandSlug = DEFAULT_BRAND;
  }

  const allowedBrands = [
    'bmw',
    'mini',
    'rolls-royce',
    'alpina',
    'ferrari',
    'nicole'
  ];

  if (!allowedBrands.includes(brandSlug)) {
    brandSlug = DEFAULT_BRAND;
  }

  /*
   * =========================================================
   * ブランド表示名
   * =========================================================
   */

  const brandMap = {
    'bmw': 'BMW',
    'mini': 'MINI',
    'rolls-royce': 'Rolls-Royce',
    'alpina': 'ALPINA',
    'ferrari': 'Ferrari',
    'nicole': 'Nicole Group'
  };

  const brand =
    brandMap[brandSlug] ||
    brandMap[DEFAULT_BRAND];

  /*
   * =========================================================
   * form_type
   * 現状はログ・将来拡張用
   * =========================================================
   */

  const formType = String(
    params.get('form_type') || 'inquiry'
  ).toLowerCase();

  /*
   * =========================================================
   * 車種・シリーズ名
   * =========================================================
   */

  const formTitleRaw =
    params.get('form_title') ||
    sessionStorage.getItem('ng_form_title') ||
    '';

  const seriesValue = normalizeTitle(formTitleRaw);

  /*
   * =========================================================
   * ブランド別formrunフォーム
   * =========================================================
   */

  const formIdMap = {
    'bmw': '@nicole-group-contact-bmw',
    'mini': '@nicole-group-contact-mini',
    'rolls-royce': '@nicole-group-contact-rollsroyce',
    'alpina': '@nicole-group-contact-alpina',
    'ferrari': '@nicole-group-contact-ferrari',
    'nicole': '@nicole-group-contact'
  };

  /*
   * =========================================================
   * ブランド別シリーズ項目
   * =========================================================
   */

  const seriesFieldMap = {
    'bmw': '_field_20',
    'mini': '_field_21',
    'rolls-royce': '_field_19',
    'alpina': '_field_19',
    'ferrari': '_field_23',
    'nicole': '_field_19'
  };

  const formId =
    formIdMap[brandSlug] ||
    formIdMap[DEFAULT_BRAND];

  const seriesFieldKey =
    seriesFieldMap[brandSlug] ||
    seriesFieldMap[DEFAULT_BRAND];

  /*
   * =========================================================
   * formrunへ渡す初期値を作成
   * =========================================================
   */

  const formParams = new URLSearchParams();

  /*
   * ブランド
   */
  formParams.set('_field_19', brand);

  /*
   * シリーズ
   */
  if (seriesValue && seriesFieldKey) {
    formParams.set(seriesFieldKey, seriesValue);
  }

  /*
   * スペースを「+」ではなく「%20」に統一
   */
  const queryString = formParams
    .toString()
    .replace(/\+/g, '%20');

  const formrunFormValue =
    formId +
    (queryString ? '?' + queryString : '');

  /*
   * =========================================================
   * formrun埋め込み要素へ設定
   * =========================================================
   */

  const embedElement = document.getElementById(
    'formrun-embed'
  );

  if (!embedElement) {
    console.error(
      'formrun-embed が見つかりません。'
    );
    return;
  }

  embedElement.setAttribute(
    'data-formrun-form',
    formrunFormValue
  );

  /*
   * 送信完了後は、formrunで設定した外部完了ページを
   * iframe内ではなくブラウザ全体で表示します。
   */
  embedElement.setAttribute(
    'data-formrun-redirect',
    'true'
  );

  /*
   * =========================================================
   * フォーム上部へスクロール
   * =========================================================
   */

  function getScrollOffset() {
    return window.matchMedia(
      '(max-width: 767px)'
    ).matches
      ? SCROLL_OFFSET_SP
      : SCROLL_OFFSET_PC;
  }

  function scrollToFormTop() {
    const wrapper = document.getElementById(
      'formrun-wrapper'
    );

    if (!wrapper) {
      return;
    }

    const targetPosition =
      window.scrollY +
      wrapper.getBoundingClientRect().top -
      getScrollOffset();

    window.scrollTo({
      top: Math.max(targetPosition, 0),
      behavior: 'smooth'
    });
  }

  /*
   * 同じタイミングで複数の監視処理が反応しても、
   * スクロール処理を重複させない
   */
  let scrollTimer = null;

  function scheduleScrollToFormTop() {
    if (scrollTimer) {
      window.clearTimeout(scrollTimer);
    }

    scrollTimer = window.setTimeout(function () {
      scrollToFormTop();
      scrollTimer = null;
    }, SCROLL_DELAY);
  }

  /*
   * =========================================================
   * formrun iframeの高さ変化を監視
   *
   * 入力画面 → 確認画面
   * 確認画面 → 入力画面
   *
   * の切り替え時にフォーム上部へ戻します。
   *
   * 送信完了後はdata-formrun-redirect="true"により、
   * ブラウザ全体で外部完了ページへ遷移します。
   * =========================================================
   */

  let observerArmed = false;
  let lastIframeHeight = 0;

  window.setTimeout(function () {
    observerArmed = true;
  }, OBSERVER_ARM_DELAY);

  function getIframeHeight(iframe) {
    if (!iframe) {
      return 0;
    }

    const rectHeight =
      iframe.getBoundingClientRect().height;

    const attributeHeight = parseFloat(
      iframe.getAttribute('height') || '0'
    );

    const styleHeight = parseFloat(
      iframe.style.height || '0'
    );

    return Math.max(
      rectHeight || 0,
      attributeHeight || 0,
      styleHeight || 0
    );
  }

  function handleIframeHeightChange(iframe) {
    const currentHeight = getIframeHeight(iframe);

    if (!currentHeight) {
      return;
    }

    if (!lastIframeHeight) {
      lastIframeHeight = currentHeight;
      return;
    }

    const heightDifference = Math.abs(
      currentHeight - lastIframeHeight
    );

    lastIframeHeight = currentHeight;

    if (
      !observerArmed ||
      heightDifference < HEIGHT_CHANGE_THRESHOLD
    ) {
      return;
    }

    scheduleScrollToFormTop();
  }

  /*
   * =========================================================
   * formrun SDKによって生成されるiframeを監視
   * =========================================================
   */

  const iframeCreationObserver =
    new MutationObserver(function () {
      const iframe =
        embedElement.querySelector('iframe');

      if (!iframe) {
        return;
      }

      if (
        iframe.getAttribute(
          'data-nicole-formrun-observer'
        ) === 'true'
      ) {
        return;
      }

      iframe.setAttribute(
        'data-nicole-formrun-observer',
        'true'
      );

      lastIframeHeight = getIframeHeight(iframe);

      /*
       * style属性・height属性の変更を監視
       */
      const iframeAttributeObserver =
        new MutationObserver(function () {
          handleIframeHeightChange(iframe);
        });

      iframeAttributeObserver.observe(iframe, {
        attributes: true,
        attributeFilter: [
          'style',
          'height'
        ]
      });

      /*
       * 実際の表示サイズ変更も監視
       */
      if ('ResizeObserver' in window) {
        const iframeResizeObserver =
          new ResizeObserver(function () {
            handleIframeHeightChange(iframe);
          });

        iframeResizeObserver.observe(iframe);
      }

      iframeCreationObserver.disconnect();

      console.log(
        'formrun iframe height observer started.'
      );
    });

  iframeCreationObserver.observe(embedElement, {
    childList: true,
    subtree: true
  });

  /*
   * =========================================================
   * formrun公式埋め込みスクリプトを読み込む
   * =========================================================
   */

  const scriptUrl =
    'https://sdk.form.run/js/v2/embed.js';

  const existingScript = document.querySelector(
    'script[src="' + scriptUrl + '"]'
  );

  if (!existingScript) {
    const script = document.createElement('script');

    script.src = scriptUrl;
    script.async = true;

    script.onerror = function () {
      console.error(
        'formrun埋め込みスクリプトの読み込みに失敗しました。'
      );
    };

    document.body.appendChild(script);
  }

  /*
   * =========================================================
   * デバッグログ
   * =========================================================
   */

  console.log('brandSlug:', brandSlug);
  console.log('brand:', brand);
  console.log('formType:', formType);
  console.log('formTitleRaw:', formTitleRaw);
  console.log('seriesValue:', seriesValue);
  console.log('seriesFieldKey:', seriesFieldKey);
  console.log('formrunFormValue:', formrunFormValue);
})();
